<script setup lang="ts">
import { computed, onMounted, reactive, ref, watch } from 'vue'
import { ElButton, ElInput, ElMessage } from 'element-plus'
import { date } from '../../utils/format'
import { request, notifyError } from '../../api/client'
import { effortLabels, type Effort } from '../../utils/reasoningEffort'
const props=defineProps<{embedding?:boolean}>()
interface Provider {id:string;name:string;base_url:string;api_format:string;models:string[]}
interface Model {id:string;name?:string;category_label?:string;source?:string;chat_compatible?:boolean;vision?:boolean;audio?:boolean;input_modalities?:string[];dimensions?:number;context_tokens?:number;output_tokens?:number;capability_status?:string;embedding_input?:string;embedding_source?:string}
interface SavedConfig {reasoning_effort?:Effort|null;provider?:string;api_format?:string;base_url?:string;model?:string;max_tokens?:number;context_tokens?:number;compression_ratio?:number;vision_enabled?:boolean;audio_enabled?:boolean;dimensions?:number;context_enabled?:boolean;multimodal_enabled?:boolean;key_configured?:boolean}
interface Saved {model_config?:SavedConfig;config?:SavedConfig;updated_at:string|null}
const providers=ref<Provider[]>([]), options=ref<Model[]>([]), updated=ref<string|null>(null), keyConfigured=ref(false), busy=ref(false), ready=ref(false), loadFailed=ref(false), notice=ref('')
const effortLevels = ref<Effort[]>([])
const form=reactive({reasoning_effort:null as Effort|null,provider:'openai',api_format:'openai',base_url:'',model:'',api_key:'',max_tokens:1024,context_tokens:128000,compression_ratio:0.6,vision_enabled:false,audio_enabled:false,dimensions:1024,context_enabled:true,multimodal_enabled:false,use_chat_key:false})
watch(() => [form.provider, form.api_format, form.model], ([provider, api_format, model], _, cleanup) => {
  effortLevels.value = []
  if (props.embedding || !model) return
  const controller = new AbortController()
  const timer = setTimeout(async () => {
    try {
      const options = await request<Effort[]>('/model-providers/effort-levels?' + new URLSearchParams({provider, api_format, model}), 'GET', undefined, controller.signal)
      if (!controller.signal.aborted && Array.isArray(options)) effortLevels.value = options
    } catch (error) { if (!controller.signal.aborted) notifyError(error) }
  }, 250)
  cleanup(() => { clearTimeout(timer); controller.abort() })
})
let savedTarget:SavedConfig={}
const groups=computed(()=>{const values=new Map<string,Model[]>();for(const item of options.value){const label=item.category_label||'其他模型';values.set(label,[...(values.get(label)||[]),item])}return [...values].map(([label,items])=>({label,items}))})
const selectedModel=computed(()=>options.value.find(item=>item.id===form.model))
const capabilityKnown=computed(()=>{const m=selectedModel.value;return !!m && (m.capability_status==='confirmed' || m.capability_status!=='unknown' && (!!m.input_modalities?.length || typeof m.vision==='boolean' || typeof m.audio==='boolean' || props.embedding&&m.embedding_source==='official_model'))})
const endpoint=props.embedding?'/me/embedding-settings':'/me/model-settings'
function configuration(){if(props.embedding)return {provider:form.provider,base_url:form.base_url,model:form.model,api_key:form.api_key||null,dimensions:form.dimensions,context_tokens:form.context_tokens,context_enabled:form.context_enabled,multimodal_enabled:form.multimodal_enabled,use_chat_key:form.use_chat_key};return {provider:form.provider,api_format:form.api_format,reasoning_effort:form.reasoning_effort,base_url:form.base_url,model:form.model,api_key:form.api_key||null,max_tokens:form.max_tokens,context_tokens:form.context_tokens,compression_ratio:form.compression_ratio,vision_enabled:form.vision_enabled,audio_enabled:form.audio_enabled}}
function setSaved(value:Saved){const config=value.config||value.model_config||{};savedTarget={...config};Object.assign(form,props.embedding?{provider:'siliconflow',model:'BAAI/bge-m3',context_tokens:8192}: {},config,{api_key:'',use_chat_key:false});keyConfigured.value=!!config.key_configured;updated.value=value.updated_at}
function changeProvider(){generation++;const p=providers.value.find(p=>p.id===form.provider);form.base_url=p?.base_url||'';form.api_format=p?.api_format||'openai';form.api_key='';form.use_chat_key=false;form.model='';form.reasoning_effort=null;options.value=[];keyConfigured.value=false}
let generation=0
async function discover(){const ticket=++generation;const sameTarget=keyConfigured.value && savedTarget.provider===form.provider && (savedTarget.base_url||'').replace(/\/$/,'')===form.base_url.replace(/\/$/,'') && (props.embedding || savedTarget.api_format===form.api_format);if(!form.base_url || (!form.api_key && !form.use_chat_key && !sameTarget)){notice.value='填写对应地址的 Key 后读取模型目录。';return}notice.value='正在读取可用模型…';try{const result=await request<{models:Model[];notice:string}>(props.embedding?endpoint+'/options':'/me/model-options','POST',configuration());if(ticket!==generation)return;options.value=result.models;const current=result.models.find(item=>item.id===form.model);if(current && capabilityKnown.value)applyModel(current,false);notice.value=`获取 ${result.models.length} 个模型。${result.notice}`}catch(e){if(ticket===generation){notice.value=e instanceof Error?e.message:'模型目录读取失败'}}}
function applyModel(item:Model,reset:boolean){form.vision_enabled=!!item.vision||!!item.input_modalities?.includes('image');form.audio_enabled=!!item.audio||!!item.input_modalities?.includes('audio');form.multimodal_enabled=form.vision_enabled||item.embedding_input==='multimodal'&&!item.input_modalities?.length;if(item.context_tokens&&(reset||form.context_tokens>item.context_tokens))form.context_tokens=item.context_tokens;if(item.output_tokens&&form.max_tokens>item.output_tokens)form.max_tokens=item.output_tokens;if(item.dimensions&&(reset||form.dimensions>item.dimensions))form.dimensions=item.dimensions}
function selectModel(event:Event){const target=event.target;if(!(target instanceof HTMLSelectElement))return;form.model=target.value;form.reasoning_effort=null;const item=options.value.find(x=>x.id===target.value);if(item)applyModel(item,true)}
async function save(){if(!props.embedding && selectedModel.value?.chat_compatible===false){ElMessage.error('该模型不支持当前文本聊天接口');return}busy.value=true;try{const body=props.embedding?{...configuration(),updated_at:updated.value}:{model_config_input:configuration(),updated_at:updated.value};const saved=await request<Saved>(endpoint,'PUT',body);setSaved(saved);ElMessage.success('模型配置已保存')}catch(e){notifyError(e)}finally{busy.value=false}}
async function load(){loadFailed.value=false;try{const [catalog,saved]=await Promise.all([request<Provider[]>('/model-providers'),request<Saved>(endpoint)]);providers.value=props.embedding?catalog.filter(p=>['openai','qwen','glm','siliconflow','openrouter','custom'].includes(p.id)):catalog;setSaved(saved);if(!form.base_url)form.base_url=providers.value.find(p=>p.id===form.provider)?.base_url||'';ready.value=true;if(keyConfigured.value)void discover()}catch(e){loadFailed.value=true;notifyError(e)}}
onMounted(load)
</script>
<template><section class="card"><h2 :data-guide-target="embedding ? undefined : 'models'">{{ embedding?'嵌入模型配置':'聊天模型配置' }}</h2><p class="sub">保存前会发送少量测试请求，可能产生费用；校验失败保留原配置。</p><el-button v-if="loadFailed" @click="load">重新读取配置</el-button><form @submit.prevent="save"><fieldset :disabled="!ready || busy"><div class="formgrid"><label class="field">模型平台<select class="form-control" v-model="form.provider" @change="changeProvider"><option v-for="p in providers" :key="p.id" :value="p.id">{{ p.name }}</option></select></label><label v-if="!embedding" class="field">API 格式<select class="form-control" v-model="form.api_format" :disabled="form.provider!=='custom'" @change="form.reasoning_effort=null;generation++;options=[];discover()"><option value="openai">OpenAI</option><option value="anthropic">Anthropic</option><option value="gemini">Gemini</option></select></label><label class="field">API 根地址<el-input placeholder=" " v-model="form.base_url" :readonly="form.provider!=='custom'" @input="generation++;options=[]" @blur="discover"/></label><label class="field">API Key<el-input v-model="form.api_key" type="password" autocomplete="new-password" :placeholder="keyConfigured?'已保存；同地址留空保留':'请输入 Key'" @input="generation++;options=[]" @blur="discover"/></label><label v-if="embedding"><input v-model="form.use_chat_key" type="checkbox" @change="generation++;options=[];discover()">复用同平台同地址聊天 Key</label><label class="field">可用模型<select class="form-control" :value="form.model" @change="selectModel"><option value="">手动填写模型 ID</option><optgroup v-for="group in groups" :key="group.label" :label="group.label"><option v-for="model in group.items" :key="model.id" :value="model.id" :disabled="!embedding && model.chat_compatible===false">{{ model.name || model.id }}{{ model.name && model.name!==model.id ? ' · '+model.id : '' }}{{ model.source==='name_hint'?'（推测）':'' }}</option></optgroup><option v-if="!options.length" v-for="model in providers.find(p=>p.id===form.provider)?.models || []" :key="model" :value="model">{{ model }}</option></select><el-button @click="discover">刷新可用模型</el-button><small>{{ notice }}</small><small v-if="selectedModel">{{ selectedModel.category_label || '模型能力未确认' }} · {{ selectedModel.context_tokens ? '窗口 '+selectedModel.context_tokens+' Token' : '窗口未公布' }}{{ selectedModel.output_tokens ? ' · 输出上限 '+selectedModel.output_tokens : '' }}{{ selectedModel.dimensions ? ' · '+selectedModel.dimensions+' 维' : '' }}</small></label><label class="field">模型 ID<el-input placeholder=" " v-model="form.model" @input="form.reasoning_effort=null" required maxlength="160"/></label><label v-if="embedding" class="field">向量维度<input placeholder=" " class="form-control" v-model.number="form.dimensions" type="number" min="64" max="4096" required></label><label v-if="embedding"><input v-model="form.context_enabled" type="checkbox">手动设置上下文窗口</label><label class="field">上下文窗口（Token）<input placeholder=" " class="form-control" v-model.number="form.context_tokens" type="number" :disabled="embedding&&!form.context_enabled" :min="embedding?512:2048" :max="embedding?1000000:10000000"></label><label v-if="embedding"><input v-model="form.multimodal_enabled" type="checkbox" :disabled="capabilityKnown">支持图片嵌入</label><template v-if="!embedding"><label class="field">默认推理强度<select class="form-control" v-model="form.reasoning_effort"><option :value="null">模型默认</option><option v-for="level in effortLevels" :key="level" :value="level">{{ effortLabels[level] }}</option></select></label><label class="field">最大输出 Token<input placeholder=" " class="form-control" v-model.number="form.max_tokens" type="number" min="128" max="10000000"></label><label class="field">压缩比例<input placeholder=" " class="form-control" v-model.number="form.compression_ratio" type="number" min="0.1" max="0.95" step="0.01"></label><label><input v-model="form.vision_enabled" type="checkbox" :disabled="capabilityKnown">支持图片输入</label><label><input v-model="form.audio_enabled" type="checkbox" :disabled="capabilityKnown">支持音频输入</label></template></div></fieldset><div class="actions model-save-actions"><el-button type="primary" native-type="submit" :disabled="!ready" :loading="busy">保存{{ embedding?'嵌入':'模型' }}配置</el-button><span class="sub model-saved-at" role="status">{{ updated ? '上次保存于 '+date(updated) : '尚未配置' }}</span></div></form></section></template>
